css:
 .banner-container {
  font-size: 16px;
  width: min(750px,100%);
  margin-inline: auto;
  line-height: 1.35;
  color: #fff;
  background-image: linear-gradient(0deg, #fff, #a9a9a9 50%, #686868);
  font-family: serif;
}

@media (max-width: 500px) {
   .banner-container {
    font-size: 2.8vw;
  }
}

 .banner-wrapper {
  padding: 2em 1.5em;
  display: grid;
  place-items: center;
}

 .banner-title {
  width: fit-content;
  margin-inline: auto;
}

 .banner-title .text {
  font-size: 2em;
  position: relative;
  z-index: 2;
}

 .banner-title.has-shadow {
  position: relative;
}

 .banner-title.has-shadow::before {
  content: "";
  display: block;
  width: 100%;
  height: 0.5em;
  background-color: #000;
  position: absolute;
  bottom: -.25em;
  left: 0;
  z-index: 1;
  border-radius: 1000px;
  filter: blur(0.5em);
}

 .banner-content {
  position: relative;
  display: grid;
  place-items: center;
  height: 100%;
}

 .banner-content .content-img {
  width: 90%;
  aspect-ratio: 1;
  margin-inline: auto;
  margin-top: 1.5em;
}

 .banner-content .content-img img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

 .banner-content .baloon {
  width: 100%;
  position: absolute;
  display: grid;
  grid-template-columns: repeat(2, 50%);
  place-items: center;
  row-gap: 8.25em;
}

 .banner-content .baloon [class*="baloon-"] {
  width: 90%;
  aspect-ratio: 600/373;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  display: grid;
  place-items: center;
}

 .banner-content .baloon [class*="baloon-"] .text {
  font-size: 0.875em;
  text-align: center;
  line-height: 1.8;
}

 .banner-content .baloon-left-top {
  padding: 0 0 2em;
  background-image: url("/uploads/fcd0afa4d9dd278e125cad45b19dde66b4cec7eec0dbb8b3eaec071d6803ebf8.webp");
}

 .banner-content .baloon-left-bottom {
  padding: 2em 0 0;
  background-image: url("/uploads/14499180d6ef1082c1c214ad8d1ddafa880954443322f588bf271f9d32e94ad2.webp");
}

 .banner-content .baloon-right-top {
  padding: 0 0 2em;
  background-image: url("/uploads/95037db77d5a775b0899054598eea9af75a059afa77ac7e40002179196707613.webp");
}

 .banner-content .baloon-right-bottom {
  padding: 2em 0 0;
  background-image: url("/uploads/978f5a83679038691c6bd96a18d6c06a36ebacd2a5c8a8b829584dd1688ecd3a.webp");
}


@media (max-width: 500px) {

 .banner-wrapper {
  padding: 2em 0.5em;
}
  .banner-content .content-img {
    width: 100%;
}
.banner-content .baloon [class*="baloon-"] {
  width: 96%;
}

}

 img {
  width: 100%;
  height: auto;
}

 * {
  box-sizing: border-box;
}

.widget-container {
  font-size: 16px;
  width: min(100%, 750px);
  margin-inline: auto;

}

.speech-header {
  display: flex;
  align-items: center;
  gap: 1em;
}

.speech-header .image {
  width: 10em;
  flex-grow: 1
}

.speech-header .image img {
  width: 100%;
  height: auto;
}

.speech-header .message {
  flex-grow: 1;
}

.speech-header .message .text {
  font-size: 1.5em;
  font-weight: 600;
  line-height: 1.2;
  color: #35a491;
}

.speech-header .message .profile {
  font-size: 1em;
  font-weight: 600;
  margin-top: .25em;
}

.speech-content {
  font-size: 1.2em;
  padding: 1em;
  background-color: #f0f0f0;
  border-radius: 1em;
  position: relative;
}

.speech-content::before {
  content: "";
  position: absolute;
  top: -0.9em;
  left: 20%;
  width: 1em;
  aspect-ratio: 1;
  background-color: #f0f0f0;
  clip-path: polygon(0 0, 0% 100%, 100% 100%);
}


@media (max-width: 550px) {
  .widget-container {
    font-size: 3.0vw;
  }
}

.talk-wrap {
  font-size: 15px;
  padding: 25px;
  background-color: #f5f5f5;
  border-radius: 10px;
}

@media screen and (max-width: 600px) {
  .talk-wrap {
    font-size: 12px;
  }
}

.talk-contents+.talk-contents {
  margin-top: 2em;
}

.talk-contents {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
}

.talk-contents[data-start=right] {
  flex-direction: row-reverse;
}

.talk-icon {
  width: 15%;
  max-width: 150px;
  height: auto;
}

.talk-icon img {
  width: 100%;
  height: auto;
  border-radius: 20vw;
}

.talk-contents .talk-box {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  max-width: calc(85% - 2em);
}

.talk-contents[data-start=left] .talk-box {
  align-items: flex-start;
  margin-left: 2em;
}

.talk-contents[data-start=right] .talk-box {
  margin-right: 2em;
}

.talk-contents[data-start=left] .talk-box .name {
  color: #BF1E56;
}

.talk-contents[data-start="right"] .talk-box .name {
  color: #007FB1;
}

.talk-box .talk {
  padding: 1.5em 2em;
  border-radius: 5px;
  line-height: 1.5;
}

.talk-contents[data-start=left] .talk-box .talk {
  background-color: #F8E5EF;
  border: 1px solid #cdb6c2;
  position: relative;
}

.talk-contents[data-start=right] .talk-box .talk {
  background-color: #C0F1F8;
  border: 1px solid #a1cbd1;
  position: relative;
}

.talk-contents .talk-box .talk:before {
  content: '';
  display: block;
  width: 20px;
  aspect-ratio: 1;
  position: absolute;
  top: -1px;
}

.talk-contents .talk-box .talk:after {
  content: '';
  display: block;
  width: 25px;
  height: 1px;
  border-radius: 9999px;
  position: absolute;
  top: -1px;
}

.talk-contents[data-start=left] .talk-box .talk:before {
  clip-path: polygon(0 0, 100% 0, 100% 100%);
  background: #F8E5EF;
  border-top: 1px solid #cdb6c2;
  left: -18px;

}

.talk-contents[data-start=left] .talk-box .talk:after {
  background-color: #cdb6c2;
  transform-origin: 0.5px 50%;
  left: -18px;
  transform: rotate(45deg);
}

.talk-contents[data-start=right] .talk-box .talk:before {
  clip-path: polygon(0 0, 100% 0, 0 100%);
  background: #C0F1F8;
  border-top: 1px solid #a1cbd1;
  right: -18px;

}

.talk-contents[data-start=right] .talk-box .talk:after {
  background-color: #a1cbd1;
  transform-origin: calc(100% - 0.5px) 50%;
  right: -18px;
  transform: rotate(-45deg);
}

.conversation__area p {
  margin: 0;
}

.conversation__area {
  width: calc(100% - 2em);
  height: auto;
  position: relative;
  background: #cbe1ec;
  font-size: 16px;
  padding: 1em;
  margin-top: 2em;
}

@media screen and (max-width: 600px) {
  .conversation__area {
    font-size: 12px;
  }
}

.conversation__headBox {
  position: absolute;
  top: -1.5em;
  left: 1em;
}

.conversation__headBox .head {
  color: #fff;
  font-size: 1.15em;
  font-weight: bold;
  background: #45A1CF;
  padding: 0.5em 1em;
}

.conversation__bubbleBox {
  display: flex;
  align-items: flex-start;
  margin-top: 1em;
}

.conversation__bubbleBox._right {
  justify-content: flex-end;
}

.conversation__bubbleBox._left {
  justify-items: flex-start;
}

.conversation__bubbleBox .bubble {
  width: auto;
  max-width: calc(60% - 2em);
  height: auto;
  border: 2px solid #aaa;
  border-radius: 5px;
  background: #fff;
  padding: 1em;
  position: relative;
}

.conversation__bubbleBox._right .bubble {
  order: 1;
  margin-right: 4.5%;
}

.conversation__bubbleBox._left .bubble {
  order: 2;
  margin-left: 4.5%;
}

.conversation__bubbleBox .bubble:before,
.conversation__bubbleBox .bubble:after {
  content: '';
  width: 0;
  height: 0;
  border-style: solid;
  position: absolute;
}

.conversation__bubbleBox .bubble::before {
  top: calc(1em - 2px);
}

.conversation__bubbleBox .bubble:after {
  top: 1em;
}

.conversation__bubbleBox._right .bubble:before {
  border-width: 9px 0 9px 15.6px;
  border-color: transparent transparent transparent #AAAAAA;
  right: -16px;
}

.conversation__bubbleBox._left .bubble:before {
  border-width: 9px 15.6px 9px 0;
  border-color: transparent #AAAAAA transparent transparent;
  left: -16px;
}

.conversation__bubbleBox._right .bubble:after {
  border-width: 7px 0 7px 12.1px;
  border-color: transparent transparent transparent #FFFFFF;
  right: -12px;
}

.conversation__bubbleBox._left .bubble:after {
  border-width: 7px 12.1px 7px 0;
  border-color: transparent #FFFFFF transparent transparent;
  left: -12px;
}

.conversation__bubbleBox .icon {
  width: 15%;
}

.conversation__bubbleBox._right .icon {
  order: 2;
}

.conversation__bubbleBox._left .icon {
  order: 1;
}

.conversation__bubbleBox .icon img {
  width: 100%;
  height: auto;
  object-fit: cover;
  border: 2px solid #ccc;
  border-radius: 10vw;
  aspect-ratio: 1/1;
}

.conversation__bubbleBox .icon .name {
  font-size: 0.9em;
  color: #666;
  text-align: center;
}

.conversation__whileBox {
  margin-top: 1em;
  width: 100%;
  height: auto;
}

.conversation__whileBox .while {
  font-size: 1.5em;
  color: #666;
}

.image-banner {
  font-size: 16px;
  position: relative;
  padding-top: 3em;
}

.image-banner .fukidashi {
  position: absolute;
  left: 50%;
  top: 0.5em;
  translate: -50% 0%;
  height: 3em;
  width: fit-content;
  display: grid;
  place-items: center;
  line-height: 1;
  padding: 0.25em 1.5em;
  background-color: #FFFF32;
  font-weight: 600;
  border-radius: 0.5em;
  font-size: 1.2em;
  filter: drop-shadow(3px 5px 0px #e7e727);
  z-index: 1;
  white-space: nowrap;
}

.image-banner .fukidashi::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  translate: -50% 0%;
  border: 0.75em solid transparent;
  border-top: 0.75em solid #FFFF32;
}

.image-banner img {
  width: 100%;
}

.speech-balloon {
  max-width: 100%;
  width: 600px;
  margin: 30px auto;
  display: flex;
  align-items: center;
  gap: 20px;
  opacity: 0;
  transition: opacity 1.5s;
}

.speech-balloon.is-active {
  opacity: 1;
}

.speech-balloon strong {
  font-style: normal;
  text-decoration: none;
  font-weight: bold;
  color: #e83154;
}

.speech-balloon .image {
  width: 15%;
  aspect-ratio: 1/1;
  border: 2px solid #000000;
  border-radius: 50%;
  overflow: hidden;
  box-sizing: border-box;
}

.speech-balloon .image img {
  width: 100%;
  height: 100% !important;
  vertical-align: bottom;
  object-fit: cover;
  margin: 0 auto !important;
}

.speech-balloon .text {
  width: 85%;
  border: 1px solid #000000;
  border-radius: 20px;
  padding: min(30px, 4%);
  font-size: min(4.6666666667vw, 28px);
  line-height: 1.4;
  position: relative;
  box-sizing: border-box;
}

.speech-balloon .text::before {
  content: "";
  display: inline-block;
  width: 14px;
  height: 14px;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
  position: absolute;
  top: calc(50% - 6px);
}

.speech-balloon.left .image {
  order: 1;
}

.speech-balloon.left .text {
  order: 2;
  background-color: #ecfbf8;
}

.speech-balloon.left .text::before {
  background-color: #ecfbf8;
  left: -8px;
  border-bottom: 1px solid #000000;
  border-left: 1px solid #000000;
}

.speech-balloon.right .image {
  order: 2;
}

.speech-balloon.right .text {
  order: 1;
  background-color: #ffffff;
}

.speech-balloon.right .text::before {
  background-color: #ffffff;
  right: -8px;
  border-top: 1px solid #000000;
  border-right: 1px solid #000000;
}

.talk {
  font-size: 18px;
  max-width: 750px;
  margin-left: auto;
  margin-right: auto;
}

.talk-grid {
  display: flex;
  gap: 1.5em;
}

.talk-grid-reverse {
  display: flex;
  gap: 1.5em;
  flex-direction: row-reverse;
}

.talk-left {
  width: 35%;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
}

.talk-right {
  width: 65%;
}

.talk-icon {
  position: absolute;
  width: 40%;
  aspect-ratio: 1/1;
  clip-path: circle(50%);
  top: 0;
  right: 5%;
  z-index: 1;
}

.talk-icon img {
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

.talk-info {
  font-size: 0.75em;
  background-color: #eee;
  padding: 0.75em;
  position: relative;
  margin-top: 3em;
  z-index: 0;
}

.talk-info .profile {
  font-size: 1.2em;
  width: 50%;
  margin-bottom: 0.5em;
}

.talk-info .profile span {
  display: block;
}

.talk-info .textarea {
  text-align: justify;
}

.talk-fukidashi,
.talk-fukidashi-reverse {
  padding: 1em;
  background-color: #fff;
  border: solid 2px #666;
  border-radius: 10px;
  font-size: 1.1em;
  position: relative;
  z-index: 0;
}

.talk-fukidashi::before,
.talk-fukidashi::after,
.talk-fukidashi-reverse::before,
.talk-fukidashi-reverse::after {
  content: "";
  width: 1em;
  aspect-ratio: 1/1;
  clip-path: polygon(100% 0, 100% 100%, 0 50%);
  background-color: #333;
  position: absolute;
  top: 1em;
  left: -1em;
  z-index: 1;
}

.talk-fukidashi::after,
.talk-fukidashi-reverse::after {
  z-index: 2;
  background-color: #fff;
  left: calc(-1em + 4px);
}

.talk-fukidashi-reverse::before,
.talk-fukidashi-reverse::after {
  clip-path: polygon(0 0, 0% 100%, 100% 50%);
  left: unset;
  right: -1em;
}

.talk-fukidashi-reverse::after {
  right: calc(-1em + 4px);
}

@media (max-width: 600px) {
  .talk {
    font-size: 3.6vw;
  }

  .talk-left {
    align-items: center;
  }

  .talk-icon {
    position: relative;
    width: 65%;
    right: unset;
  }

  .talk-info {
    margin-top: -1em;
    padding-top: 1.5em;
  }

  .talk-info .profile {
    width: 100%;
  }
}

