  font-size: 15px;
  padding: 25px;
  background-color: #f5f5f5;
  border-radius: 10px;
}

.talk-wrap[data-start=left] .talk-box {
  align-items: flex-start;
}

.talk-wrap[data-start=left] .talk-box:nth-of-type(even) {
  align-items: flex-end;
}

.talk-box {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.talk-box+.talk-box {
  margin-top: 15px;
}

.talk-box:nth-of-type(even) {
  align-items: flex-start;
}

.talk-box:nth-of-type(even) .talk {
  background-color: #F8E5EF;
}

.talk-box .talk {
  max-width: 75%;
  background-color: #C0F1F8;
  padding: 25px;
  border-radius: 10px;
  line-height: 1.5;
}

@media screen and (max-width: 600px) {
  .talk-wrap {
    font-size: 3vw;
  }

  .talk-box .talk {
    padding: 15px;
  }
}

p {
  margin: 0;
}

.bubble__box {
  width: 100%;
  height: auto;
  display: flex;
  align-items: flex-start;
  opacity: 0;
  transition: opacity 1s;
}

.bubble__box.is-left {
  justify-content: flex-start;
}

.bubble__box.is-right {
  justify-content: flex-end;
}

.bubble__box+.bubble__box {
  margin-top: 20px;
}

.icon__box {
  width: 90px;
  height: 90px;
  border-radius: 45px;
  background: #F9DFD5;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.bubble__box.is-left .icon__box {
  order: 1;
  margin-right: 60px;
}

.bubble__box.is-right .icon__box {
  order: 2;
  margin-left: 60px;
}

@media screen and (max-width: 600px) {
  .icon__box {
    width: 60px;
    height: 60px;
    border-radius: 30px;
  }

  .bubble__box.is-left .icon__box {
    margin-right: 40px;
  }

  .bubble__box.is-right .icon__box {
    margin-left: 40px;
  }
}

.icon__box img {
  width: 80px;
  height: 80px !important;
  border-radius: 40px;
  object-fit: cover;
}

@media screen and (max-width: 600px) {
  .icon__box img {
    width: 50px;
    height: 50px;
    border-radius: 25px;
  }
}

.icon__box:before {
  content: '';
  width: 20px;
  height: 20px;
  border-radius: 10px;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: #F9DFD5;
}

.icon__box:after {
  content: '';
  width: 30px;
  height: 30px;
  border-radius: 15px;
  position: absolute;
  top: 20%;
  transform: translateY(-20%);
  background: #F9DFD5;
}

.bubble__box.is-left .icon__box:before {
  left: 95px;
}

.bubble__box.is-left .icon__box:after {
  left: 115px;
}

.bubble__box.is-right .icon__box:before {
  right: 95px;
}

.bubble__box.is-right .icon__box:after {
  right: 115px;
}

@media screen and (max-width: 600px) {
  .icon__box:before {
    content: '';
    width: 10px;
    height: 10px;
    border-radius: 5px;
  }

  .icon__box:after {
    content: '';
    width: 15px;
    height: 15px;
    border-radius: 8px;
  }

  .bubble__box.is-left .icon__box:before {
    left: 70px;
  }

  .bubble__box.is-left .icon__box:after {
    left: 80px;
  }

  .bubble__box.is-right .icon__box:before {
    right: 70px;
  }

  .bubble__box.is-right .icon__box:after {
    right: 80px;
  }
}

.lines__box {
  width: auto;
  max-width: calc(100% - 170px);
  height: auto;
  background: #F9DFD5;
  padding: 10px;
  border-radius: 10px;
  font-size: 1em;
}

