  border-radius: 30px;
  box-sizing: border-box;
}

.balloon:before {
  content: "";
  position: absolute;
  left: -38px;
  width: 13px;
  height: 12px;
  bottom: 0;
  /*左の小さな丸い吹き出し色*/
  background-color: #fff0c6;
  border-radius: 50%;
}

.balloon:after {
  content: "";
  position: absolute;
  left: -24px;
  width: 20px;
  height: 18px;
  bottom: 3px;
  /*真ん中の丸い吹き出し色*/
  background-color: #fff0c6;
  border-radius: 50%;
}

.balloon p {
  margin: 0;
  padding: 0;
}
